# 🏦 Cuenta: `$= dv.current().nombre`

## 📊 Resumen

- **Entidad:** `$= dv.current().entidad`
- **Número:** `$= dv.current().numero`
- **Tipo:** `$= dv.current().tipo_cuenta`
- **Moneda:** `$= dv.current().moneda`
- **Saldo Inicial:** `INPUT[number:saldo_inicial]` CUP

```dataviewjs
let current = dv.current();
let saldoInicial = Number(current.saldo_inicial || 0);

// Buscar todas las transacciones financieras
let transacciones = dv.pages('#financiero');

// Función segura para verificar si una propiedad apunta a esta cuenta (como texto o enlace)
let matchesAccount = (prop) => {
    if (!prop) return false;
    let str = typeof prop === 'object' && prop.path ? prop.path : String(prop);
    return str.includes(current.file.name);
};

// Calcular Ingresos reales asociados a esta cuenta
let ingresos = transacciones
    .where(p => p.operacion === "income" || p.income === true)
    .where(p => matchesAccount(p.place_of_entry))
    .amount.array().reduce((a, b) => a + Number(b || 0), 0);

// Calcular Gastos reales asociados a esta cuenta
let gastos = transacciones
    .where(p => p.operacion === "spent" || p.gasto === true)
    .where(p => matchesAccount(p.place_of_spent))
    .amount.array().reduce((a, b) => a + Number(b || 0), 0);

let saldoCalculado = saldoInicial + ingresos - gastos;

// Guardar y sincronizar automáticamente el saldo en las propiedades de la nota (YAML)
const file = app.vault.getAbstractFileByPath(current.file.path);
if (file) {
    app.fileManager.processFrontMatter(file, (fm) => {
        if (fm.saldo_actual !== saldoCalculado) {
            fm.saldo_actual = saldoCalculado;
        }
    });
}

dv.paragraph(`### 💰 Saldo Actual: **${saldoCalculado} ${current.moneda || 'CUP'}**`);
```

