### 📊 Comparativa: Presupuesto Estimado vs Gasto Real

```dataviewjs
const c = dv.current();
const moneda = c.moneda ? String(c.moneda) : "CUP";

// Definición segura de corchetes
const cAbre = String.fromCharCode(91);
const cCierra = String.fromCharCode(93);

// 1. Obtención de Mes y Año
const mesNota = c.mes ? String(c.mes).toLowerCase().trim() : "";
const anoNota = Number(c.año) || 2026;

const mesesMap = {
    "enero": 1, "febrero": 2, "marzo": 3, "abril": 4, "mayo": 5, "junio": 6,
    "julio": 7, "agosto": 8, "septiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12
};
const mesNum = mesesMap[mesNota] || 9;

// 2. Función de eliminación de acentos
function quitarAcentos(texto) {
    const conA = "áéíóúÁÉÍÓÚñÑüÜ";
    const sinA = "aeiouAEIOUnNuU";
    let res = "";
    const txt = String(texto || "");
    for (let i = 0; i < txt.length; i++) {
        const idx = conA.indexOf(txt[i]);
        res += idx !== -1 ? sinA[idx] : txt[i];
    }
    return res;
}

// 3. Extraer categoría limpia
function extraerCategoria(cat) {
    if (cat === null || cat === undefined) return "";
    if (Array.isArray(cat)) cat = cat[0];

    let texto = "";
    if (typeof cat === "object" && cat !== null) {
        if (typeof cat.fileName === "string") texto = cat.fileName;
        else if (typeof cat.path === "string") texto = String(cat.path).split("/").pop().replace(".md", "");
        else if (typeof cat.display === "string") texto = cat.display;
        else texto = String(cat);
    } else {
        texto = String(cat);
    }

    texto = String(texto || "");
    texto = texto.split(cAbre).join("").split(cCierra).join("").split('"').join("").split("'").join("");
    return quitarAcentos(texto.trim().toLowerCase());
}

// 4. Categorías configuradas
const categoriasConfig = [
    { nombre: "Alimentación", clave: "presupuesto_alimentacion" },
    { nombre: "Familia", clave: "presupuesto_familia" },
    { nombre: "Transporte", clave: "presupuesto_transporte" },
    { nombre: "Ocio", clave: "presupuesto_ocio" },
    { nombre: "Hogar", clave: "presupuesto_hogar" },
    { nombre: "Personal", clave: "presupuesto_personal" },
    { nombre: "Aseo", clave: "presupuesto_aseo" },
    { nombre: "Teléfono", clave: "presupuesto_telefono" },
    { nombre: "Salud", clave: "presupuesto_salud" },
    { nombre: "Préstamo", clave: "presupuesto_prestamo" },
    { nombre: "Otros", clave: "presupuesto_otros" },
    { nombre: "Electricidad", clave: "presupuesto_electricidad" }
];

// 5. Filtrar gastos
const gastos = dv.pages('"003 AREAS/Económica/Finanzas/Transacciones/Spent"')
    .where(function(p) {
        let pMesNum = null;
        let pAnoVal = null;

        if (p.date) {
            if (typeof p.date.month === "number") {
                pMesNum = p.date.month;
                pAnoVal = p.date.year;
            } else if (typeof p.date === "string") {
                const d = new Date(p.date);
                if (!isNaN(d.getTime())) {
                    pMesNum = d.getMonth() + 1;
                    pAnoVal = d.getFullYear();
                }
            }
        } else if (p.created && p.created.month) {
            pMesNum = p.created.month;
            pAnoVal = p.created.year;
        } else if (p.file && p.file.cday) {
            pMesNum = p.file.cday.month;
            pAnoVal = p.file.cday.year;
        }

        const pMesProp = p.mes ? String(p.mes).toLowerCase().trim() : null;
        const coincideMes = (pMesProp && pMesProp === mesNota) || (pMesNum && mesNum && pMesNum === mesNum);
        const pAnoProp = p.año ? Number(p.año) : null;
        const coincideAno = (pAnoProp && pAnoProp === anoNota) || (pAnoVal && pAnoVal === anoNota) || !anoNota;

        return coincideMes && coincideAno;
    });

// 6. Acumulado por categoría
const acumuladoGastos = {};
for (const g of gastos) {
    if (g.spending_category && g.amount != null) {
        const catKey = extraerCategoria(g.spending_category);
        const monto = Number(g.amount) || 0;
        acumuladoGastos[catKey] = (acumuladoGastos[catKey] || 0) + monto;
    }
}

// 7. Procesar datos
const etiquetas = [];
const valoresPresupuesto = [];
const valoresGastoReal = [];
let maxMonto = 1000;
const resumenFilas = [];

for (const item of categoriasConfig) {
    const estimado = Math.max(0, Number(c[item.clave]) || 0);
    const real = Math.max(0, Number(acumuladoGastos[extraerCategoria(item.nombre)]) || 0);
    const disponible = estimado - real;

    etiquetas.push('"' + item.nombre + '"');
    valoresPresupuesto.push(estimado);
    valoresGastoReal.push(real);

    if (estimado > maxMonto) maxMonto = estimado;
    if (real > maxMonto) maxMonto = real;

    let difTexto = "";
    if (disponible < 0) {
        difTexto = '<span style="color: #f87171; font-weight: bold;">🚨 -' + Math.abs(disponible).toLocaleString() + ' ' + moneda + '</span>';
    } else {
        difTexto = '<span style="color: #34d399; font-weight: bold;">✅ +' + disponible.toLocaleString() + ' ' + moneda + '</span>';
    }

    resumenFilas.push([
        "**" + item.nombre + "**",
        estimado.toLocaleString() + " " + moneda,
        real.toLocaleString() + " " + moneda,
        difTexto
    ]);
}

maxMonto = Math.ceil((maxMonto * 1.15) / 1000) * 1000;

// 8. Configuración con colores de alto contraste para ejes en Android
const configTemaDark = "%%{init: {'theme': 'dark', 'themeVariables': {'textColor': '#FFD54F', 'labelColor': '#FFD54F', 'xyChart': {'titleColor': '#FFFFFF', 'xAxisLabelColor': '#FFD54F', 'xAxisTitleColor': '#FFD54F', 'yAxisLabelColor': '#FFD54F', 'yAxisTitleColor': '#FFD54F', 'plotColorPalette': '#00E5FF, #FF1744'}}}}%%";

const mermaidCode = [
    configTemaDark,
    "xychart-beta",
    '    title "Barras: Estimado | Linea: Gasto Real"',
    "    x-axis " + cAbre + etiquetas.join(", ") + cCierra,
    '    y-axis "Monto (' + moneda + ')" 0 --> ' + maxMonto,
    "    bar " + cAbre + valoresPresupuesto.join(", ") + cCierra,
    "    line " + cAbre + valoresGastoReal.join(", ") + cCierra
].join("\n");

dv.paragraph("```mermaid\n" + mermaidCode + "\n```");

// 9. Renderizar tabla de saldos
dv.span("**🔍 Desglose de Gastos y Saldo Disponible por Categoría:**");
dv.table(["Categoría", "Presupuesto Planificado", "Gasto Real Acumulado", "Saldo Disponible"], resumenFilas);
```

