# 📉 Resumen de Ingresos del Mes
```dataviewjs
let current = dv.current();
let mesNota = current.mes; 
let añoNota = current.año; 

// Mapeo para convertir el nombre del mes escrito en número
const mesesMap = {
    "enero": 1, "febrero": 2, "marzo": 3, "abril": 4, "mayo": 5, "junio": 6,
    "julio": 7, "agosto": 8, "septiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12
};
let numMes = mesesMap[mesNota ? String(mesNota).toLowerCase() : ""];

// Obtener todas las transacciones de INGRESO de este mes
let ingresos = dv.pages('"003 AREAS/Económica/Finanzas/Transacciones/Income"')
    .where(p => {
        if (p.mes === mesNota) return true;
        if (p.date && p.date.month === numMes && p.date.year === añoNota) return true;
        if (p.created && p.created.month === numMes && p.created.year === añoNota) return true;
        return false;
    });

// Mapeo de categorías de ingresos
let categoriasControladas = [
    { nombre: "Salario", limite: current.presupuesto_salario },
    { nombre: "Venta", limite: current.presupuesto_venta },
    { nombre: "Regalo", limite: current.presupuesto_regalo },
    { nombre: "Negocio", limite: current.presupuesto_negocio },
    { nombre: "Plus", limite: current.presupuesto_plus },
    { nombre: "Freelance", limite: current.presupuesto_freelance }
];

// 1. Presupuesto Income Estimado (Suma de metas/límites)
let presupuesto_income_estimado = categoriasControladas
    .reduce((acc, cat) => acc + Number(cat.limite || 0), 0);

// 2. Presupuesto Income Ejecutado / Real (Suma de ingresos realizados)
let presupuesto_income_ejecutado = ingresos.amount.array()
    .reduce((a, b) => a + Number(b || 0), 0);

// 3. Presupuesto Income Pendiente (Diferencia entre estimado y ejecutado)
let presupuesto_income_pendiente = presupuesto_income_estimado - presupuesto_income_ejecutado;

// Guardar/Actualizar automáticamente las propiedades en el Frontmatter (YAML)
const file = app.vault.getAbstractFileByPath(current.file.path);
if (file) {
    app.fileManager.processFrontMatter(file, (fm) => {
        if (fm.presupuesto_income_estimado !== presupuesto_income_estimado ||
            fm.presupuesto_income_ejecutado !== presupuesto_income_ejecutado ||
            fm.presupuesto_income_pendiente !== presupuesto_income_pendiente) {

            fm.presupuesto_income_estimado = presupuesto_income_estimado;
            fm.presupuesto_income_ejecutado = presupuesto_income_ejecutado;
            fm.presupuesto_income_pendiente = presupuesto_income_pendiente;
        }
    });
}

let filas = [];

for (let cat of categoriasControladas) {
    let totalIngresado = ingresos
        .where(p => {
            if (!p.input_source) return false;
            if (p.input_source.path) return p.input_source.path.includes(cat.nombre);
            if (Array.isArray(p.input_source)) return p.input_source.some(link => link && link.path && link.path.includes(cat.nombre));
            if (typeof p.input_source === 'string') return p.input_source.includes(cat.nombre);
            return false;
        })
        .amount.array().reduce((a, b) => a + Number(b || 0), 0);

    let limite = Number(cat.limite) || 0;
    let restante = limite - totalIngresado;
    let porcentaje = limite > 0 ? Math.round((totalIngresado / limite) * 100) : 0;

    let estado = "🔴 Crítico";
    if (porcentaje >= 90 && porcentaje < 100) estado = "🟡 Cerca de meta";
    if (porcentaje >= 100) estado = "🎉 Meta cumplida";

    filas.push([
        `[[${cat.nombre}]]`, 
        limite + " CUP", 
        totalIngresado + " CUP", 
        restante + " CUP", 
        porcentaje + "%", 
        estado
    ]);
}

// Callout de resumen con los tres globales
dv.paragraph(`> [!info] **Resumen de Ingresos del Mes**
> - **Presupuesto Estimado:** \`${presupuesto_income_estimado} CUP\`
> - **Presupuesto Ejecutado:** \`${presupuesto_income_ejecutado} CUP\`
> - **Presupuesto Pendiente:** \`${presupuesto_income_pendiente} CUP\``);

// Tabla detallada por categorías
dv.table(["Categoría", "Meta Asignada", "Ingreso Real", "Falta", "% Conseguido", "Estado"], filas);

```
