        if (p.created && p.created.month === numMes && p.created.year === añoNota) return true;
        return false;
    });

// Mapeo de categorías reales con sus presupuestos definidos en el YAML
let categoriasControladas = [
    { nombre: "Alimentación", limite: current.presupuesto_alimentacion },
    { nombre: "Transporte", limite: current.presupuesto_transporte },
    { nombre: "Ocio", limite: current.presupuesto_ocio },
    { nombre: "Salud", limite: current.presupuesto_salud },
    { nombre: "Teléfono", limite: current.presupuesto_telefono },
    { nombre: "Hogar", limite: current.presupuesto_hogar },
    { nombre: "Aseo", limite: current.presupuesto_aseo },
    { nombre: "Familia", limite: current.presupuesto_familia },
    { nombre: "Electricidad", limite: current.presupuesto_electricidad },
    { nombre: "Otros", limite: current.presupuesto_otros }
];

// 1. Presupuesto Spent Estimado (Suma de los presupuestos asignados a cada categoría)
let presupuesto_spent_estimado = categoriasControladas
    .reduce((acc, cat) => acc + Number(cat.limite || 0), 0);

// 2. Presupuesto Spent Ejecutado (Suma de todos los gastos realizados)
let presupuesto_spent_ejecutado = transacciones.amount.array()
    .reduce((a, b) => a + Number(b || 0), 0);

// 3. Presupuesto Spent Disponible (Diferencia entre el estimado y el ejecutado)
let presupuesto_spent_disponible = presupuesto_spent_estimado - presupuesto_spent_ejecutado;

// Guardar/Actualizar automáticamente las propiedades en el Frontmatter (YAML)
const file = app.vault.getAbstractFileByPath(current.file.path);
if (file) {
    app.fileManager.processFrontMatter(file, (fm) => {
        if (fm.presupuesto_spent_estimado !== presupuesto_spent_estimado ||
            fm.presupuesto_spent_ejecutado !== presupuesto_spent_ejecutado ||
            fm.presupuesto_spent_disponible !== presupuesto_spent_disponible) {

            fm.presupuesto_spent_estimado = presupuesto_spent_estimado;
            fm.presupuesto_spent_ejecutado = presupuesto_spent_ejecutado;
            fm.presupuesto_spent_disponible = presupuesto_spent_disponible;
        }
    });
}

let filas = [];

for (let cat of categoriasControladas) {
    // Sumar gastos que correspondan a esta categoría
    let totalGastado = transacciones
        .where(p => {
            if (!p.spending_category) return false;
            if (p.spending_category.path) return p.spending_category.path.includes(cat.nombre);
            if (Array.isArray(p.spending_category)) return p.spending_category.some(link => link && link.path && link.path.includes(cat.nombre));
            if (typeof p.spending_category === 'string') return p.spending_category.includes(cat.nombre);
            return false;
        })
        .amount.array().reduce((a, b) => a + Number(b || 0), 0);

    let limite = Number(cat.limite) || 0;
    let restante = limite - totalGastado;
    let porcentaje = limite > 0 ? Math.round((totalGastado / limite) * 100) : 0;

    // Alerta visual de límite excedido
    let estado = "🟢 Sano";
    if (porcentaje >= 90 && porcentaje < 100) estado = "🟡 Al límite";
    if (porcentaje >= 100) estado = "🔴 Excedido";

    filas.push([
        `[[${cat.nombre}]]`, 
        limite + " CUP", 
        totalGastado + " CUP", 
        restante + " CUP", 
        porcentaje + "%", 
        estado
    ]);
}

// Callout de resumen visual de gastos
dv.paragraph(`> [!info] **Resumen de Gastos del Mes**
> - **Presupuesto Estimado:** \`${presupuesto_spent_estimado} CUP\`
> - **Presupuesto Ejecutado:** \`${presupuesto_spent_ejecutado} CUP\`
> - **Presupuesto Disponible:** \`${presupuesto_spent_disponible} CUP\``);

// Tabla detallada por categorías
dv.table(["Categoría", "Presupuesto Asignado", "Gasto Real", "Restante", "% Consumido", "Estado"], filas);

