let current = dv.current();
let saldoInicial = Number(current.saldo_inicial || 0);

// Buscar todas las transacciones financieras
let transacciones = dv.pages('#financiero');

// Función segura para verificar si una propiedad apunta a esta cuenta (como texto o enlace)
let matchesAccount = (prop) => {
    if (!prop) return false;
    let str = typeof prop === 'object' && prop.path ? prop.path : String(prop);
    return str.includes(current.file.name);
};

// Calcular Ingresos reales asociados a esta cuenta
